create schema private_mfa_challenge_history;
revoke all on schema private_mfa_challenge_history from public,anon,authenticated,service_role;
create table private_mfa_challenge_history.cleanup_receipt(singleton boolean primary key default true check(singleton),main_sha text not null,before_sha text not null,before_image_text text not null,result jsonb not null,cleaned_at timestamptz not null default clock_timestamp());
create table private_mfa_challenge_history.price_receipt(singleton boolean primary key default true check(singleton),main_sha text not null,cleanup_sha text not null,state_sha text not null,recorded_at timestamptz not null default clock_timestamp());
revoke all on all tables in schema private_mfa_challenge_history from public,anon,authenticated,service_role;
create function private_mfa_challenge_history.require(ok boolean,message text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'MFA_CHALLENGE_HISTORY: %',message;end if;end$$;
