 (517590::bigint,'2025/26',7,10708::bigint,10704::bigint,'50903328','42e69f86ca5c83257a88c4eabcc6c11548b0363e831f0fc106d96e88bd3be53d',34883::bigint,31,5),
 (517620::bigint,'2025/26',11,10705::bigint,10708::bigint,'50903358','8c27d0353b260e4ef333c5f7c27d0d11cd43b52434ee4e880c7fae8fa35dbe3e',34887::bigint,29,5),
